message.content:
{
  "candidate_edge_types": [
    {
      "name": "ATTEMPTS_TO_REPAIR",
      "definition": "A subsequent agent action attempts to resolve a failure or error identified during an earlier execution step.",
      "source_description": "An earlier observed execution failure or error.",
      "target_description": "A subsequent agent action intended to resolve that failure."
    },
    {
      "name": "PRIOR_SETUP_ENABLES_SUBSEQUENT_ACTION",
      "definition": "A successful environment or resource preparation result establishes a capability that is a precondition for a later action, which depends on that capability being available.",
      "source_description": "A successful installation or setup observation that provides a required capability.",
      "target_description": "A later action that relies on the capability established by the setup."
    },
    {
      "name": "CONFLICTING_RESULTS_TRIGGER_DISAMBIGUATING_ANALYSIS",
      "definition": "Multiple mutually inconsistent outputs produced by alternative analyses prompt the agent to perform additional targeted analysis to determine which result is correct.",
      "source_description": "A set of divergent results produced by alternative methods applied to the same problem.",
      "target_description": "A follow-up analysis action designed to discriminate among the divergent results."
    },
    {
      "name": "REUSES_PRIOR_RESULT_AS_INPUT",
      "definition": "A result that was previously derived, evaluated, or selected is supplied as an input to a subsequent action.",
      "source_description": "An earlier produced, evaluated, or selected result such as a derived structure or value.",
      "target_description": "A later action that consumes that earlier result as an input."
    },
    {
      "name": "VERIFIES_PRODUCED_OUTPUT",
      "definition": "The agent inspects an artifact it produced to confirm that it matches the required format or expected content.",
      "source_description": "An artifact generated by an earlier action.",
      "target_description": "An inspection action that checks the artifact's correctness or completeness."
    },
    {
      "name": "VERIFIED_RESULTS_JUSTIFY_COMPLETION",
      "definition": "The agent concludes the task after confirming through inspection that its produced artifacts satisfy the stated requirements.",
      "source_description": "A verification observation confirming that the required outputs are present and correct.",
      "target_description": "A task-completion action declaring the work finished."
    }
  ]
}

